                mv.visitTypeInsn(Opcodes.INSTANCEOF, RTTIinterface);

                //if not, pop and try the next match
                mv.visitJumpInsn(Opcodes.IFNE, ahead);
                mv.visitInsn(Opcodes.POP);
                mv.visitJumpInsn(Opcodes.GOTO, if_fail);

